import nordest as N
for name, hour in (('today', N.HOUR_TODAY), ('southern lines full', N.HOUR_FULL)):
    s = N.service(hour)
    print(f'--- {name}: TGVs an hour on each line {hour}')
    print('trains a platform track takes an hour:', s['per_track'])
    print('through trains each way between a southern line and the north or east:', s['through_each_way'])
    print('trains each way on the direct link Montparnasse to Gare de Lyon:', s['link_each_way'])
    for k, v in s['flows'].items(): print('  ', k, v)
    for st in ('nordest', 'lyon', 'montparnasse'):
        print(f'   {st}: {s[st + "_stops"]} stops an hour (both ways), the rule asks for {s[st + "_tracks_calc"]} tracks, {s[st + "_load"]:.2f} trains an hour on each track')
